css:
.print-format {
	 margin: 0 !important;
	 padding: 0 !important;
	 font-family: Poppins;
	 --std-pad: 0.8cm;
	 --col-pri: #133c55;
}
 .print-format th {
	 background: none !important;
	 color: black !important;
	 font-weight: 600;
}
 .print-format td, .print-format th {
	 vertical-align: top !important;
}
 .print-format ol, .print-format ul {
	 padding-left: 11px !important;
}
 .si-status {
	 font-size: 20px;
	 display: inline;
	 padding: 0.4rem 1.6rem;
	 vertical-align: middle;
	 border-radius: 8px;
	 color: white;
}
.si-status.paid {
	 background: #87cc9b;
}
 .si-status.unpaid {
	 background: #fc4547;
}
 .header {
	 background-color: hsl(202.73deg 34% 91%);
	 padding: var(--std-pad);
}
 .middle {
	 flex: 1;
	 display: flex;
	 flex-direction: column;
	 margin: var(--std-pad);
	 margin-top: 0;
	 border: 1px solid var(--col-pri);
	 border-radius: 6px;
	 overflow: hidden;
}
 .middle table thead {
	 background: var(--col-pri);
}
 .middle table thead * {
	 color: white !important;
}
 .footer > table {
	 border-collapse: separate;
	 background-color: hsl(202.73deg 34% 91%);
	 border-spacing: var(--std-pad);
}
 .invoice-details {
	 padding: var(--std-pad);
}
 .si-label {
	 font-size: 9px;
	 font-weight: 600;
	 color: #9d9fa4;
}
 .si-bq {
	 padding: 2px 6px;
	 background: hsl(202.73deg 34% 91%);
	 width: fit-content;
	 border-left: 2px solid var(--col-pri);
}
 .si-bq.si-filled {
	 color: var(--col-pri);
}
 .si-value {
	 font-size: 9px;
	 font-weight: 600;
	 color: #9d9fa4;
}
 .si-value > b {
	 color: #000;
	 padding-right: 3px;
}
 .si-headline {
	 font-size: 16px;
	 font-weight: 700;
	 color: #000;
}
 .si-body {
	 font-size: 10px;
	 color: #787e8b;
}
 .si-body > b, .si-body * > b {
	 color: #000;
	 font-weight: 600;
}
 .si-body b[title] {
	 font-size: 13px;
}
 .si-normal {
	 font-size: 13px;
	 color: #787e8b;
}
 .main-row td:first-child {
	 padding-left: 16px !important;
}
 .main-row td:last-child {
	 padding-right: 16px !important;
}
 .main-row td {
	 vertical-align: middle !important;
	 padding-top: 12px !important;
	 padding-bottom: 12px !important;
}
 .main-row:not(.head):nth-child(odd) {
	 background: hsl(202.73deg 34% 91%);
}
 table {
	 width: 100%;
	 font-size: 14px;
}
 .print-format table[data-no-pad] td {
	 padding: 0 !important;
}
 .print-format *[data-no-pad] {
	 padding: 0 !important;
}
 .print-format *[data-v-pad] {
	 padding: 4px !important;
	 padding-left: 0 !important;
	 padding-right: 0 !important;
}
 hr {
	 margin: 0cm 0 !important;
	 border-top: 2px solid #000 !important;
}
 .print-container {
	 display: flex;
	 flex: 1;
	 flex-direction: column;
}
 [data-left] {
	 text-align: left;
}
 [data-center] {
	 text-align: center;
}
 [data-right] {
	 text-align: right;
}
 table.compressed td, table.compressed th {
	 padding: 4px 3px !important;
}
 .spacer {
	 width: 100%;
	 height: 20px;
}
 .terms ol, .terms ul {
	 padding-left: 0;
	 font-weight: 600;
}
 td[data-compressed], th[data-compressed], tr[data-compressed] td, tr[data-compressed] th, table[data-compressed] td, table[data-compressed] th {
	 padding: 3px 6px !important;
}
 [no-break] {
	 white-space: nowrap;
}
 [dib] {
	 display: inline-block;
}
 [bl] {
	 border-left: 2px solid black;
}
 [br] {
	 border-right: 2px solid black;
}
 [bt] {
	 border-top: 2px solid black;
}
 [bb] {
	 border-bottom: 2px solid black;
}
 [tc] {
	 text-align: center;
}
 [tr] {
	 text-align: right;
}
 [tl] {
	 text-align: left;
}
 @page {
	 size: A4;
	 margin: 0;
}
